notes" maxlength="1000" required></div><div class="suite-actions"><button class="btn btn-sm btn-outline-secondary suite-add-line" type="button"><i class="fas fa-plus mr-1"></i> Add Item</button><button class="btn btn-sm btn-primary" type="submit"><i class="fas fa-exchange-alt mr-1"></i> Transfer Stock</button></div></form>
